package com.finance.controller;
import com.finance.model.RecurringTransaction;import com.finance.repository.RecurringRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.List;
@RestController @RequestMapping("/api/recurring") public class RecurringController {private final RecurringRepository repo;public RecurringController(RecurringRepository r){repo=r;}public record Request(@NotBlank String type,@NotBlank String category,@NotBlank String description,@Positive long amountPaise,@NotBlank String frequency,@NotNull LocalDate nextDate,boolean active){}@GetMapping public List<RecurringTransaction> all(Authentication a){return repo.findByUserId(uid(a));}@PostMapping public RecurringTransaction create(@Valid @RequestBody Request r,Authentication a){RecurringTransaction t=new RecurringTransaction();t.setUserId(uid(a));apply(t,r);return repo.save(t);}@PutMapping("/{id}") public RecurringTransaction update(@PathVariable String id,@Valid @RequestBody Request r,Authentication a){var t=repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(t,r);return repo.save(t);}@DeleteMapping("/{id}") public void delete(@PathVariable String id,Authentication a){repo.delete(repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}private void apply(RecurringTransaction t,Request r){t.setType(r.type());t.setCategory(r.category());t.setDescription(r.description());t.setAmountPaise(r.amountPaise());t.setFrequency(r.frequency());t.setNextDate(r.nextDate());t.setActive(r.active());}private String uid(Authentication a){return (String)a.getPrincipal();}}
